// 雜湊集合：只從「序列起點」（x-1 不存在）開始往上數
// 時間複雜度: O(n)，空間複雜度: O(n)
function longestConsecutive(nums) {
    const set = new Set(nums);
    let best = 0;
    for (const x of set) {
        if (set.has(x - 1))
            continue; // 不是起點，跳過
        let len = 1;
        while (set.has(x + len))
            len++;
        best = Math.max(best, len);
    }
    return best;
}

