class Solution:
    def longestConsecutive(self, nums: List[int]) -> int:
        num_set = set(nums)
        longest = 0

        for x in num_set:
            # 只從序列的起點開始展開
            if x - 1 in num_set:
                continue
            length = 1
            cur = x
            while cur + 1 in num_set:
                cur += 1
                length += 1
            longest = max(longest, length)

        return longest

